package com.example.sgva.usecases

import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.FormatoPeriodoInvalidoException
import com.example.sgva.domain.IndicadorCalidad
import com.example.sgva.domain.ReporteEjecutivo
import com.example.sgva.domain.ResultadoAutoevaluacion

/**
 * Consolida el reporte ejecutivo (Fase 4 del anteproyecto — integración de
 * reportes): agrupa los indicadores de calidad de los Módulos 1 y 2 con las
 * respuestas de encuesta de percepción del Módulo 3 ya registradas. Por
 * composición sobre los casos de uso de cálculo ya existentes (mismo patrón
 * que [GenerarMatrizRadarUseCase]); no accede al repositorio directamente.
 *
 * La exportación a un formato físico concreto (PDF) es responsabilidad
 * exclusiva de la infraestructura (`GeneradorReportePdf`); este caso de uso
 * solo produce el [ReporteEjecutivo], un objeto de dominio puro.
 */
class GenerarReporteEjecutivoUseCase(
    private val calcularEvolucionMatricula: CalcularEvolucionMatriculaUseCase,
    private val calcularTasaDesercion: CalcularTasaDesercionUseCase,
    private val consolidarSaberPro: ConsolidarPuntajesSaberProUseCase,
    private val calcularDistribucionFormacion: CalcularDistribucionFormacionUseCase,
    private val calcularCapacidadInstalada: CalcularCapacidadInstaladaUseCase,
    private val consultarRespuestasEncuesta: ConsultarRespuestasEncuestaUseCase,
    private val calcularResultadoAutoevaluacion: CalcularResultadoAutoevaluacionUseCase,
) {

    /**
     * @param cohorte cohorte para la tasa de deserción; a diferencia de los
     *   demás indicadores, esa cohorte es obligatoria en su caso de uso
     *   (`DESIGN_SGVA.md` §2) y no tiene un valor por defecto razonable para
     *   un reporte sin cohorte específica — se incluye solo cuando se indica.
     * @param programa programa para el resultado de autoevaluación (Módulo
     *   4); al igual que la cohorte, no tiene un valor por defecto razonable
     *   y se incluye solo cuando se indica junto con [periodo].
     */
    fun ejecutar(
        periodo: String? = null,
        facultad: String? = null,
        cohorte: String? = null,
        programa: String? = null,
    ): ReporteEjecutivo {
        val indicadores = mutableListOf<IndicadorCalidad>()
        indicadores += calcularEvolucionMatricula.ejecutar(facultad)
        indicadores += sinDatosInsuficientes { consolidarSaberPro.ejecutar(facultad) }
        indicadores += sinDatosInsuficientes { calcularDistribucionFormacion.ejecutar(periodo, facultad) }
        indicadores += sinDatosInsuficientes { listOf(calcularCapacidadInstalada.ejecutar(periodo, facultad)) }

        cohorte?.trim()?.takeIf { it.isNotEmpty() }?.let { cohorteIndicada ->
            indicadores += sinDatosInsuficientes { listOf(calcularTasaDesercion.ejecutar(cohorteIndicada, facultad)) }
        }

        return ReporteEjecutivo(
            indicadores = indicadores.toList(),
            respuestasEncuesta = consultarRespuestasEncuesta.listarTodas(),
            resultadoAutoevaluacion = resultadoAutoevaluacion(programa, periodo),
        )
    }

    /**
     * El resultado de autoevaluación solo se incluye cuando se indican tanto
     * el programa como el periodo, y se omite si el periodo no tiene el
     * formato `AAAAS` esperado o si no hay ningún dato calculable para esa
     * combinación (todos los promedios ausentes), igual que las demás
     * secciones del reporte.
     */
    private fun resultadoAutoevaluacion(programa: String?, periodo: String?): ResultadoAutoevaluacion? {
        val programaIndicado = programa?.trim()?.takeIf { it.isNotEmpty() } ?: return null
        val periodoIndicado = periodo?.trim()?.takeIf { it.isNotEmpty() } ?: return null

        val resultado = try {
            calcularResultadoAutoevaluacion.ejecutar(programaIndicado, periodoIndicado)
        } catch (formatoInvalido: FormatoPeriodoInvalidoException) {
            return null
        }

        val hayDatos = resultado.promedioGlobal != null ||
            resultado.promediosPorFactor.values.any { it != null } ||
            resultado.promediosPorCaracteristica.values.any { it != null }

        return resultado.takeIf { hayDatos }
    }

    /**
     * Un reporte ejecutivo agrega lo que hay disponible: si una sección no
     * tiene datos suficientes para calcularse (ej. sin puntajes Saber Pro
     * aún), se omite en vez de impedir la generación del resto del reporte.
     */
    private fun sinDatosInsuficientes(calculo: () -> List<IndicadorCalidad>): List<IndicadorCalidad> =
        try {
            calculo()
        } catch (sinDatos: DatosInsuficientesException) {
            emptyList()
        }
}

package com.example.sgva.domain

/**
 * Una de las cuatro fases fijas del proceso institucional de autoevaluación
 * (Módulo 5, `DESIGN_SGVA.md` §0 y §1, V6): (1) apropiación; (2) planeación y
 * desarrollo; (3) emisión de juicios de valor y plan de mejoramiento; (4)
 * aprobación de resultados. No depende de frameworks, bases de datos ni
 * sistemas de archivos.
 *
 * @property ciclo identificador del [CicloAutoevaluacion] al que pertenece.
 * @property numero número de la fase, de 1 a 4 inclusive.
 * @property nombre nombre descriptivo de la fase (ver [NOMBRES]).
 */
data class FaseCiclo(
    val ciclo: String,
    val numero: Int,
    val nombre: String,
) {
    init {
        ReglasDeFormato.exigirNoVacio(ciclo, "ciclo")
        if (numero !in RANGO_NUMERO) {
            throw FaseInvalidaException(numero)
        }
        ReglasDeFormato.exigirNoVacio(nombre, "nombre")
    }

    companion object {
        /** Rango válido del número de fase (`DESIGN_SGVA.md` §0, V6). */
        val RANGO_NUMERO: IntRange = 1..4

        /**
         * Nombre canónico de cada una de las cuatro fases del proceso
         * institucional, en el orden fijado por `DESIGN_SGVA.md` §0 (V6).
         * `RegistrarCicloAutoevaluacionUseCase` las crea automáticamente para
         * cada ciclo nuevo: no varían entre ediciones.
         */
        val NOMBRES: Map<Int, String> = mapOf(
            1 to "Apropiación",
            2 to "Planeación y desarrollo",
            3 to "Emisión de juicios de valor y plan de mejoramiento",
            4 to "Aprobación de resultados",
        )
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.ActividadCiclo
import com.example.sgva.domain.AvanceCiclo
import com.example.sgva.domain.CicloNoEncontradoException
import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.ConfiguracionSeguimiento
import com.example.sgva.domain.EstadoActividad
import com.example.sgva.domain.FaseCiclo
import com.example.sgva.domain.ParticipacionConSemaforo
import java.time.LocalDate

/**
 * Módulo 5 — seguimiento del avance de un ciclo (`DESIGN_SGVA.md` §0.1 y §2,
 * V6). Para un [ciclo] y una [fechaReferencia] —recibida siempre como
 * parámetro, nunca leída del reloj del sistema (`DESIGN_SGVA.md` §0.1)—
 * calcula el avance por fase, las actividades vencidas y próximas a vencer,
 * los factores con preevaluación pendiente y la participación de los
 * actores, aplicando exactamente las reglas de `DESIGN_SGVA.md` §0.1.
 */
class CalcularAvanceCicloUseCase(
    private val repositorio: AcademicDataRepository,
    private val configuracionPonderaciones: ConfiguracionPonderaciones,
    private val configuracionSeguimiento: ConfiguracionSeguimiento,
) {

    /** @throws CicloNoEncontradoException si no existe el [ciclo] referenciado. */
    fun ejecutar(ciclo: String, fechaReferencia: LocalDate): AvanceCiclo {
        repositorio.buscarCicloPorId(ciclo) ?: throw CicloNoEncontradoException(ciclo)

        val actividades = repositorio.listarActividadesPorCiclo(ciclo)
        val actividadesPorFase = actividades.groupBy { it.fase }

        val avancePorFase = FaseCiclo.RANGO_NUMERO.associateWith { numero ->
            avanceDeFase(actividadesPorFase[numero].orEmpty())
        }
        val avanceCiclo = avancePorFase.values.filterNotNull().let { presentes ->
            if (presentes.isEmpty()) null else presentes.average()
        }

        val factoresDelGrupo = repositorio.listarGruposEvaluadorPorCiclo(ciclo).flatMap { it.factores }.toSet()
        val factoresConPendiente = factoresDelGrupo.filter { factor ->
            caracteristicasConPreevaluacionPendiente(ciclo, factor)
        }.toSet()

        val participacionConSemaforo = repositorio.listarParticipacionPorCiclo(ciclo).map { participacion ->
            ParticipacionConSemaforo(
                participacion = participacion,
                semaforo = participacion.semaforo(configuracionSeguimiento),
            )
        }

        return AvanceCiclo(
            ciclo = ciclo,
            avancePorFase = avancePorFase,
            avanceCiclo = avanceCiclo,
            actividadesVencidas = actividades.filter { it.estaVencida(fechaReferencia) },
            actividadesProximasAVencer = actividades.filter {
                it.estaProximaAVencer(fechaReferencia, configuracionSeguimiento.diasProximaAVencer)
            },
            factoresConPreevaluacionPendiente = factoresConPendiente,
            participacionActores = participacionConSemaforo,
        )
    }

    /** Regla de §0.1: completadas / total; ausente si la fase no tiene actividades. */
    private fun avanceDeFase(actividadesDeFase: List<ActividadCiclo>): Double? {
        if (actividadesDeFase.isEmpty()) return null
        val completadas = actividadesDeFase.count { it.estado == EstadoActividad.COMPLETADA }
        return completadas.toDouble() / actividadesDeFase.size
    }

    /**
     * `true` si alguna característica del [factor] no tiene ninguna
     * preevaluación registrada en el [ciclo] (`DESIGN_SGVA.md` §0.1).
     */
    private fun caracteristicasConPreevaluacionPendiente(ciclo: String, factor: String): Boolean {
        val caracteristicasDelFactor = configuracionPonderaciones.caracteristicas
            .filter { it.factor == factor }
            .map { it.id }
            .toSet()
        val caracteristicasConPreevaluacion = repositorio.listarPreevaluacionesPorCiclo(ciclo)
            .map { it.caracteristica }
            .toSet()
        return (caracteristicasDelFactor - caracteristicasConPreevaluacion).isNotEmpty()
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.CicloAutoevaluacion
import com.example.sgva.domain.DetalleCiclo

/**
 * Consulta los ciclos de autoevaluación registrados, con sus fases y
 * actividades (Módulo 5, V6). No modifica el estado del repositorio.
 */
class ConsultarCicloAutoevaluacionUseCase(
    private val repositorio: AcademicDataRepository,
) {

    /** Devuelve todos los ciclos registrados, en orden de inserción. */
    fun listarTodos(): List<CicloAutoevaluacion> = repositorio.listarCiclos()

    /** Devuelve el detalle del ciclo con [id] (fases y actividades), o `null` si no existe. */
    fun buscarDetallePorId(id: String): DetalleCiclo? {
        val ciclo = repositorio.buscarCicloPorId(id) ?: return null
        return DetalleCiclo(
            ciclo = ciclo,
            fases = repositorio.listarFasesPorCiclo(id),
            actividades = repositorio.listarActividadesPorCiclo(id),
        )
    }
}

package com.example.sgva.domain

/**
 * Puerto de salida (Outbound/Driven Port) para persistir y recuperar las
 * entidades de dominio ya validadas (`DESIGN_SGVA.md` §3).
 *
 * El dominio declara la interfaz; la tecnología concreta vive en
 * `infrastructure` y nunca al revés (Inversión de Dependencia). En esta versión
 * el único adaptador es en memoria; un futuro adaptador Spring Data debe poder
 * sustituirlo sin tocar el dominio ni los casos de uso.
 *
 * Toda entidad que entra o sale de este puerto es válida por construcción: sus
 * invariantes se verifican en el bloque `init` de [Estudiante] y [Docente], no
 * aquí ni en los adaptadores (`DESIGN_SGVA.md` §0.1).
 *
 * El identificador (`id`) es la clave de identidad de cada entidad. Este puerto
 * solo almacena y consulta; la regla de aplicación "un `id` no puede
 * registrarse dos veces" la aplican los casos de uso de registro.
 */
interface AcademicDataRepository {

    /** Persiste [estudiante] indexado por su `id` y lo devuelve sin cambios. */
    fun guardarEstudiante(estudiante: Estudiante): Estudiante

    /** Devuelve el estudiante con [id], o `null` si no hay ninguno registrado. */
    fun buscarEstudiantePorId(id: String): Estudiante?

    /** Devuelve todos los estudiantes registrados, en orden de inserción. */
    fun listarEstudiantes(): List<Estudiante>

    /** Persiste [docente] indexado por su `id` y lo devuelve sin cambios. */
    fun guardarDocente(docente: Docente): Docente

    /** Devuelve el docente con [id], o `null` si no hay ninguno registrado. */
    fun buscarDocentePorId(id: String): Docente?

    /** Devuelve todos los docentes registrados, en orden de inserción. */
    fun listarDocentes(): List<Docente>

    /** Persiste [respuesta] indexada por su `id` y la devuelve sin cambios. */
    fun guardarRespuestaEncuesta(respuesta: RespuestaEncuesta): RespuestaEncuesta

    /** Devuelve la respuesta de encuesta con [id], o `null` si no hay ninguna registrada. */
    fun buscarRespuestaEncuestaPorId(id: String): RespuestaEncuesta?

    /** Devuelve todas las respuestas de encuesta registradas, en orden de inserción. */
    fun listarRespuestasEncuesta(): List<RespuestaEncuesta>

    /** Persiste [resultado] y lo devuelve sin cambios. */
    fun guardarResultadoEncuestaPregunta(resultado: ResultadoEncuestaPregunta): ResultadoEncuestaPregunta

    /**
     * Devuelve el resultado de encuesta por pregunta cuya clave natural es
     * ([programa], [periodo], [codigoPregunta]), o `null` si no hay ninguno registrado.
     */
    fun buscarResultadoEncuestaPregunta(
        programa: String,
        periodo: String,
        codigoPregunta: String,
    ): ResultadoEncuestaPregunta?

    /** Devuelve todos los resultados de encuesta por pregunta registrados, en orden de inserción. */
    fun listarResultadosEncuestaPregunta(): List<ResultadoEncuestaPregunta>

    /** Persiste [evaluacion] y la devuelve sin cambios. */
    fun guardarEvaluacionDocumental(evaluacion: EvaluacionDocumental): EvaluacionDocumental

    /**
     * Devuelve la evaluación documental cuya clave natural es ([programa],
     * [periodo], [caracteristica]), o `null` si no hay ninguna registrada.
     */
    fun buscarEvaluacionDocumental(
        programa: String,
        periodo: String,
        caracteristica: String,
    ): EvaluacionDocumental?

    /** Devuelve todas las evaluaciones documentales registradas, en orden de inserción. */
    fun listarEvaluacionesDocumentales(): List<EvaluacionDocumental>

    // ===== Módulo 5 — Seguimiento del proceso institucional (V6) =====

    /** Persiste [ciclo] y lo devuelve sin cambios. */
    fun guardarCiclo(ciclo: CicloAutoevaluacion): CicloAutoevaluacion

    /** Devuelve el ciclo con [id], o `null` si no hay ninguno registrado. */
    fun buscarCicloPorId(id: String): CicloAutoevaluacion?

    /** Devuelve el ciclo cuya clave natural es ([programa], [periodo]), o `null` si no hay ninguno registrado. */
    fun buscarCicloPorProgramaYPeriodo(programa: String, periodo: String): CicloAutoevaluacion?

    /** Devuelve todos los ciclos registrados, en orden de inserción. */
    fun listarCiclos(): List<CicloAutoevaluacion>

    /** Persiste [fase] y la devuelve sin cambios. */
    fun guardarFase(fase: FaseCiclo): FaseCiclo

    /** Devuelve las fases del [ciclo], en orden de inserción. */
    fun listarFasesPorCiclo(ciclo: String): List<FaseCiclo>

    /** Persiste [actividad] y la devuelve sin cambios. */
    fun guardarActividad(actividad: ActividadCiclo): ActividadCiclo

    /** Devuelve las actividades del [ciclo], en orden de inserción. */
    fun listarActividadesPorCiclo(ciclo: String): List<ActividadCiclo>

    /** Persiste [grupo] y lo devuelve sin cambios. */
    fun guardarGrupoEvaluador(grupo: GrupoEvaluador): GrupoEvaluador

    /**
     * Devuelve el grupo evaluador cuya clave natural es ([ciclo], [taller]),
     * o `null` si no hay ninguno registrado.
     */
    fun buscarGrupoEvaluador(ciclo: String, taller: Int): GrupoEvaluador?

    /** Devuelve los grupos evaluadores del [ciclo], en orden de inserción. */
    fun listarGruposEvaluadorPorCiclo(ciclo: String): List<GrupoEvaluador>

    /** Persiste [preevaluacion] y la devuelve sin cambios. */
    fun guardarPreevaluacion(preevaluacion: PreevaluacionEvaluador): PreevaluacionEvaluador

    /**
     * Devuelve la preevaluación cuya clave natural es ([ciclo],
     * [caracteristica], [evaluador]), o `null` si no hay ninguna registrada.
     */
    fun buscarPreevaluacion(ciclo: String, caracteristica: String, evaluador: String): PreevaluacionEvaluador?

    /** Devuelve las preevaluaciones del [ciclo], en orden de inserción. */
    fun listarPreevaluacionesPorCiclo(ciclo: String): List<PreevaluacionEvaluador>

    /** Persiste [participacion] y la devuelve sin cambios. */
    fun guardarParticipacion(participacion: ParticipacionActor): ParticipacionActor

    /**
     * Devuelve la participación cuya clave natural es ([ciclo], [actor]), o
     * `null` si no hay ninguna registrada.
     */
    fun buscarParticipacion(ciclo: String, actor: String): ParticipacionActor?

    /** Devuelve las participaciones del [ciclo], en orden de inserción. */
    fun listarParticipacionPorCiclo(ciclo: String): List<ParticipacionActor>

    /** Persiste [proyecto] y lo devuelve sin cambios. */
    fun guardarProyecto(proyecto: ProyectoMejoramiento): ProyectoMejoramiento

    /** Devuelve el proyecto con [id], o `null` si no hay ninguno registrado. */
    fun buscarProyectoPorId(id: String): ProyectoMejoramiento?

    /** Devuelve todos los proyectos de mejoramiento registrados, en orden de inserción. */
    fun listarProyectos(): List<ProyectoMejoramiento>
}

