package com.example.sgva.usecases

import com.example.sgva.domain.ComparacionResultados
import com.example.sgva.domain.DiferenciaResultado
import com.example.sgva.domain.ResultadoAutoevaluacion

/**
 * Módulo 5 — comparación del resultado de autoevaluación de un programa
 * entre ciclos (`DESIGN_SGVA.md` §0.1 y §2, V6). Reutiliza
 * [CalcularResultadoAutoevaluacionUseCase] para cada periodo y calcula, por
 * factor y global, la diferencia entre cada par de periodos consecutivos en
 * el orden recibido. Una diferencia con un valor ausente en cualquiera de
 * los dos periodos es ausente, nunca `0` (`DESIGN_SGVA.md` §0.1).
 */
class CompararResultadosEntreCiclosUseCase(
    private val calcularResultadoAutoevaluacion: CalcularResultadoAutoevaluacionUseCase,
) {

    fun ejecutar(programa: String, periodos: List<String>): ComparacionResultados {
        val resultados = periodos.map { calcularResultadoAutoevaluacion.ejecutar(programa, it) }

        val diferencias = resultados.zipWithNext { base, comparado ->
            DiferenciaResultado(
                periodoBase = base.periodo,
                periodoComparado = comparado.periodo,
                diferenciasPorFactor = diferenciaPorFactor(base, comparado),
                diferenciaGlobal = diferencia(base.promedioGlobal, comparado.promedioGlobal),
            )
        }

        return ComparacionResultados(programa = programa, resultados = resultados, diferencias = diferencias)
    }

    private fun diferenciaPorFactor(
        base: ResultadoAutoevaluacion,
        comparado: ResultadoAutoevaluacion,
    ): Map<String, Double?> =
        (base.promediosPorFactor.keys + comparado.promediosPorFactor.keys).associateWith { factor ->
            diferencia(base.promediosPorFactor[factor], comparado.promediosPorFactor[factor])
        }

    private fun diferencia(base: Double?, comparado: Double?): Double? =
        if (base == null || comparado == null) null else comparado - base
}

package com.example.sgva.domain

/**
 * Reglas de formato compartidas por las entidades del dominio. Centraliza la
 * verificación del formato `AAAAS` para que `Estudiante.cohorte` y
 * `Docente.periodo` apliquen exactamente el mismo criterio.
 */
internal object ReglasDeFormato {

    /** Regex de referencia definida en `DESIGN_SGVA.md`, Sección 0.1. */
    private val PATRON_PERIODO_ACADEMICO = Regex("""^\d{4}[12]$""")

    /**
     * Verifica que [valor] cumpla el formato `AAAAS` y lo devuelve sin cambios.
     *
     * @throws FormatoPeriodoInvalidoException si el formato no es válido.
     */
    fun exigirPeriodoAcademico(valor: String, campo: String): String {
        if (!PATRON_PERIODO_ACADEMICO.matches(valor)) {
            throw FormatoPeriodoInvalidoException(campo, valor)
        }
        return valor
    }

    /**
     * Verifica que [valor] no esté vacío ni en blanco y lo devuelve sin cambios.
     *
     * @throws CampoRequeridoVacioException si el valor está en blanco.
     */
    fun exigirNoVacio(valor: String, campo: String): String {
        if (valor.isBlank()) {
            throw CampoRequeridoVacioException(campo)
        }
        return valor
    }

    /**
     * Verifica que [valor] contenga al menos un elemento y lo devuelve sin
     * cambios. Aplica a los conjuntos obligatorios de la entidad (ej.
     * `ResultadoEncuestaPregunta.estamentos`).
     *
     * @throws CampoRequeridoVacioException si el conjunto está vacío.
     */
    fun <T> exigirNoVacio(valor: Set<T>, campo: String): Set<T> {
        if (valor.isEmpty()) {
            throw CampoRequeridoVacioException(campo)
        }
        return valor
    }

    /** Tolerancia numérica para las sumas de ponderaciones (`DESIGN_SGVA.md` §0.1). */
    const val TOLERANCIA_SUMA_PONDERACIONES: Double = 0.001

    /**
     * Verifica que [valor] no sea negativo y lo devuelve sin cambios. Aplica a
     * todo peso del modelo de ponderaciones (factores, características y
     * mezcla encuestas/documental; `DESIGN_SGVA.md` §0.1).
     *
     * @throws PonderacionNegativaException si [valor] es negativo.
     */
    fun exigirPonderacionNoNegativa(valor: Double, contexto: String): Double {
        if (valor < 0.0) {
            throw PonderacionNegativaException(contexto, valor)
        }
        return valor
    }

    /**
     * Verifica que [suma] sea igual a `1.0` dentro de
     * [TOLERANCIA_SUMA_PONDERACIONES] y la devuelve sin cambios.
     *
     * @throws SumaPonderacionesInvalidaException si [suma] se aleja de `1.0` más que la tolerancia.
     */
    fun exigirSumaUno(suma: Double, contexto: String): Double {
        if (kotlin.math.abs(suma - 1.0) > TOLERANCIA_SUMA_PONDERACIONES) {
            throw SumaPonderacionesInvalidaException(contexto, suma)
        }
        return suma
    }
}

package com.example.sgva.infrastructure.web

import com.example.sgva.infrastructure.reporting.GeneradorReportePdf
import com.example.sgva.usecases.GenerarReporteEjecutivoUseCase
import org.springframework.http.ContentDisposition
import org.springframework.http.HttpHeaders
import org.springframework.http.MediaType
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.RestController

/**
 * Adaptador de entrada REST (Primary Adapter) de los reportes ejecutivos
 * (Fase 4 del anteproyecto — integración de reportes, `DESIGN_SGVA.md` §4).
 * Delega la consolidación de datos en [GenerarReporteEjecutivoUseCase] y la
 * generación física del PDF en [GeneradorReportePdf]; no reimplementa
 * lógica de negocio ni de renderizado.
 */
@RestController
@RequestMapping("/api/reportes")
class ReporteController(
    private val generarReporteEjecutivo: GenerarReporteEjecutivoUseCase,
    private val generadorReportePdf: GeneradorReportePdf,
) {

    @GetMapping("/ejecutivo", produces = [MediaType.APPLICATION_PDF_VALUE])
    fun obtenerReporteEjecutivo(
        @RequestParam periodo: String?,
        @RequestParam facultad: String?,
        @RequestParam cohorte: String?,
        @RequestParam programa: String?,
    ): ResponseEntity<ByteArray> {
        val reporte = generarReporteEjecutivo.ejecutar(periodo, facultad, cohorte, programa)
        val pdf = generadorReportePdf.generar(reporte)

        val nombreArchivo = periodo?.trim()?.takeIf { it.isNotEmpty() }
            ?.let { "reporte-ejecutivo-$it.pdf" }
            ?: "reporte-ejecutivo.pdf"

        return ResponseEntity.ok()
            .contentType(MediaType.APPLICATION_PDF)
            .header(
                HttpHeaders.CONTENT_DISPOSITION,
                ContentDisposition.attachment().filename(nombreArchivo).build().toString(),
            )
            .body(pdf)
    }
}

package com.example.sgva.infrastructure.reporting

import com.example.sgva.domain.ReporteEjecutivo
import org.apache.pdfbox.pdmodel.PDDocument
import org.apache.pdfbox.pdmodel.PDPage
import org.apache.pdfbox.pdmodel.PDPageContentStream
import org.apache.pdfbox.pdmodel.common.PDRectangle
import org.apache.pdfbox.pdmodel.font.PDFont
import org.apache.pdfbox.pdmodel.font.PDType1Font
import org.apache.pdfbox.pdmodel.font.Standard14Fonts
import org.springframework.stereotype.Component
import java.io.ByteArrayOutputStream
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

/**
 * Genera el PDF físico de un [ReporteEjecutivo] (Fase 4 del anteproyecto —
 * integración de reportes, `DESIGN_SGVA.md` §4). Única clase del proyecto que
 * depende de la librería de generación de documentos (Apache PDFBox); el
 * dominio y los casos de uso no la conocen ni dependen de ella.
 */
@Component
class GeneradorReportePdf {

    fun generar(reporte: ReporteEjecutivo): ByteArray {
        PDDocument().use { documento ->
            val lienzo = LienzoReporte(documento)

            lienzo.titulo("Reporte Ejecutivo SGVA")
            lienzo.subtitulo("Generado el " + FORMATO_FECHA.format(LocalDateTime.now()))

            lienzo.seccion("Indicadores de Calidad")
            if (reporte.indicadores.isEmpty()) {
                lienzo.linea("No hay indicadores disponibles.")
            } else {
                lienzo.tabla(
                    encabezados = listOf("Nombre", "Valor", "Periodo", "Facultad"),
                    anchos = listOf(220f, 70f, 90f, 120f),
                    filas = reporte.indicadores.map {
                        listOf(it.nombre, "%.2f".format(it.valor), it.periodo, it.facultad)
                    },
                )
            }

            lienzo.seccion("Respuestas de Encuesta")
            if (reporte.respuestasEncuesta.isEmpty()) {
                lienzo.linea("No hay respuestas de encuesta registradas.")
            } else {
                lienzo.tabla(
                    encabezados = listOf("Id", "Estamento", "Factor", "Calificación", "Periodo"),
                    anchos = listOf(80f, 90f, 180f, 80f, 70f),
                    filas = reporte.respuestasEncuesta.map {
                        listOf(it.id, it.estamento.name, it.factor, it.calificacion.toString(), it.periodo)
                    },
                )
            }

            reporte.resultadoAutoevaluacion?.let { resultado ->
                lienzo.seccion("Resultado de Autoevaluación")
                lienzo.linea("Programa: ${resultado.programa} - Periodo: ${resultado.periodo}")
                lienzo.tabla(
                    encabezados = listOf("Nivel", "Identificador", "Promedio"),
                    anchos = listOf(110f, 150f, 90f),
                    filas = buildList {
                        add(listOf("Global", "-", formatoPromedio(resultado.promedioGlobal)))
                        resultado.promediosPorFactor.forEach { (factor, promedio) ->
                            add(listOf("Factor", factor, formatoPromedio(promedio)))
                        }
                        resultado.promediosPorCaracteristica.forEach { (caracteristica, promedio) ->
                            add(listOf("Característica", caracteristica, formatoPromedio(promedio)))
                        }
                    },
                )
            }

            lienzo.cerrar()

            return ByteArrayOutputStream().use { salida ->
                documento.save(salida)
                salida.toByteArray()
            }
        }
    }

    private fun formatoPromedio(valor: Double?): String = valor?.let { "%.2f".format(it) } ?: "Sin datos"

    companion object {
        private val FORMATO_FECHA = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")
    }
}

/**
 * Maneja el posicionamiento vertical y la paginación automática del PDF:
 * abre una página nueva cuando el contenido no cabe en la actual. Cada
 * fragmento de texto se dibuja en su propio bloque `beginText`/`endText` con
 * coordenadas absolutas, evitando la aritmética de desplazamientos relativos
 * de PDFBox.
 */
private class LienzoReporte(private val documento: PDDocument) {

    private val fuenteTitulo = PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD)
    private val fuenteSeccion = PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD)
    private val fuenteTexto = PDType1Font(Standard14Fonts.FontName.HELVETICA)

    private val margenIzquierdo = 50f
    private val margenSuperior = 50f
    private val margenInferior = 50f
    private val altoLinea = 16f

    private var contenido: PDPageContentStream = abrirPagina()
    private var y: Float = alturaUtilInicial()

    fun titulo(texto: String) {
        dibujar(texto, margenIzquierdo, y, fuenteTitulo, 18f)
        y -= 26f
    }

    fun subtitulo(texto: String) {
        dibujar(texto, margenIzquierdo, y, fuenteTexto, 10f)
        y -= 24f
    }

    fun seccion(texto: String) {
        asegurarEspacio(altoLinea * 2)
        dibujar(texto, margenIzquierdo, y, fuenteSeccion, 13f)
        y -= altoLinea
    }

    fun linea(texto: String) {
        asegurarEspacio(altoLinea)
        dibujar(texto, margenIzquierdo, y, fuenteTexto, 10f)
        y -= altoLinea
    }

    fun tabla(encabezados: List<String>, anchos: List<Float>, filas: List<List<String>>) {
        asegurarEspacio(altoLinea)
        filaTabla(encabezados, anchos, fuenteSeccion)
        val yLineaSeparadora = y + 4f
        contenido.moveTo(margenIzquierdo, yLineaSeparadora)
        contenido.lineTo(margenIzquierdo + anchos.sum(), yLineaSeparadora)
        contenido.stroke()
        y -= altoLinea

        for (fila in filas) {
            asegurarEspacio(altoLinea)
            filaTabla(fila, anchos, fuenteTexto)
            y -= altoLinea
        }
        y -= altoLinea / 2
    }

    fun cerrar() {
        contenido.close()
    }

    private fun filaTabla(valores: List<String>, anchos: List<Float>, fuente: PDFont) {
        var x = margenIzquierdo
        for ((valor, ancho) in valores.zip(anchos)) {
            dibujar(ajustarAncho(valor, fuente, 9f, ancho), x, y, fuente, 9f)
            x += ancho
        }
    }

    private fun dibujar(texto: String, x: Float, y: Float, fuente: PDFont, tamano: Float) {
        contenido.beginText()
        contenido.setFont(fuente, tamano)
        contenido.newLineAtOffset(x, y)
        contenido.showText(texto)
        contenido.endText()
    }

    private fun ajustarAncho(texto: String, fuente: PDFont, tamano: Float, anchoMaximo: Float): String {
        if (anchoTexto(texto, fuente, tamano) <= anchoMaximo) return texto
        var recorte = texto
        while (recorte.isNotEmpty() && anchoTexto("$recorte...", fuente, tamano) > anchoMaximo) {
            recorte = recorte.dropLast(1)
        }
        return if (recorte.isEmpty()) texto else "$recorte..."
    }

    private fun anchoTexto(texto: String, fuente: PDFont, tamano: Float): Float =
        fuente.getStringWidth(texto) / 1000f * tamano

    private fun asegurarEspacio(alturaNecesaria: Float) {
        if (y - alturaNecesaria < margenInferior) {
            contenido.close()
            contenido = abrirPagina()
            y = alturaUtilInicial()
        }
    }

    private fun abrirPagina(): PDPageContentStream {
        val pagina = PDPage(PDRectangle.LETTER)
        documento.addPage(pagina)
        return PDPageContentStream(documento, pagina)
    }

    private fun alturaUtilInicial(): Float = PDRectangle.LETTER.height - margenSuperior
}

package com.example.sgva.domain

/**
 * Participación de un actor en las encuestas de un [CicloAutoevaluacion]
 * (Módulo 5, `DESIGN_SGVA.md` §0.1 y §1, V6). No depende de frameworks,
 * bases de datos ni sistemas de archivos.
 *
 * Su clave natural es la combinación de [ciclo] y [actor]: no tiene un `id`
 * propio. [actor] es un texto abierto, no uno de los siete [TipoEstamento]:
 * la fuente institucional agrupa actores de forma distinta (ej. empleadores
 * y aliados estratégicos juntos).
 *
 * @property ciclo identificador del [CicloAutoevaluacion] al que pertenece.
 * @property actor texto abierto que identifica al actor.
 * @property poblacion tamaño de la población del actor; entero no negativo.
 * @property muestra tamaño de la muestra; entero no negativo, `muestra <= poblacion`.
 * @property respuestas respuestas recibidas; entero no negativo, `respuestas <= muestra`.
 */
data class ParticipacionActor(
    val ciclo: String,
    val actor: String,
    val poblacion: Int,
    val muestra: Int,
    val respuestas: Int,
) {
    init {
        ReglasDeFormato.exigirNoVacio(ciclo, "ciclo")
        ReglasDeFormato.exigirNoVacio(actor, "actor")
        if (poblacion < 0) throw CantidadNegativaException("poblacion", poblacion)
        if (muestra < 0) throw CantidadNegativaException("muestra", muestra)
        if (respuestas < 0) throw CantidadNegativaException("respuestas", respuestas)
        if (muestra > poblacion) {
            throw ParticipacionInconsistenteException(
                "La muestra ($muestra) no puede ser mayor que la población ($poblacion).",
            )
        }
        if (respuestas > muestra) {
            throw ParticipacionInconsistenteException(
                "Las respuestas ($respuestas) no pueden ser mayores que la muestra ($muestra).",
            )
        }
    }

    /**
     * Porcentaje diligenciado (`DESIGN_SGVA.md` §0.1): respuestas / muestra,
     * ausente si la muestra es `0`.
     */
    val porcentajeDiligenciado: Double?
        get() = if (muestra == 0) null else respuestas.toDouble() / muestra

    /**
     * Semáforo de participación derivado de [porcentajeDiligenciado] según
     * los umbrales de [configuracion] (`DESIGN_SGVA.md` §0.1). No es una
     * propiedad almacenada: los umbrales siempre provienen de una fuente de
     * configuración externa, nunca se hardcodean en el dominio.
     */
    fun semaforo(configuracion: ConfiguracionSeguimiento): TipoSemaforo? =
        configuracion.semaforoDe(porcentajeDiligenciado)
}

package com.example.sgva.infrastructure.reporting

import com.example.sgva.domain.IndicadorCalidad
import com.example.sgva.domain.ReporteEjecutivo
import com.example.sgva.domain.ResultadoAutoevaluacion
import com.example.sgva.domain.RespuestaEncuesta
import com.example.sgva.domain.TipoEstamento
import org.apache.pdfbox.Loader
import org.apache.pdfbox.text.PDFTextStripper
import org.junit.jupiter.api.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

class GeneradorReportePdfTest {

    private val generador = GeneradorReportePdf()

    @Test
    fun `genera bytes de un PDF valido con el contenido del reporte`() {
        val reporte = ReporteEjecutivo(
            indicadores = listOf(
                IndicadorCalidad(IndicadorCalidad.TASA_DESERCION, 12.5, "20231", "Ingeniería"),
            ),
            respuestasEncuesta = listOf(
                RespuestaEncuesta("R001", TipoEstamento.ESTUDIANTE, "Infraestructura", 4, "20261"),
            ),
        )

        val pdf = generador.generar(reporte)

        assertTrue(pdf.isNotEmpty())
        assertEquals("%PDF", String(pdf.copyOfRange(0, 4), Charsets.US_ASCII))

        val texto = extraerTexto(pdf)
        assertTrue(texto.contains("Reporte Ejecutivo SGVA"))
        assertTrue(texto.contains(IndicadorCalidad.TASA_DESERCION))
        assertTrue(texto.contains("R001"))
        assertTrue(texto.contains("Infraestructura"))
    }

    @Test
    fun `las secciones sin datos muestran un mensaje en vez de una tabla vacia`() {
        val reporte = ReporteEjecutivo(indicadores = emptyList(), respuestasEncuesta = emptyList())

        val texto = extraerTexto(generador.generar(reporte))

        assertTrue(texto.contains("No hay indicadores disponibles."))
        assertTrue(texto.contains("No hay respuestas de encuesta registradas."))
    }

    @Test
    fun `incluye el resultado de autoevaluacion con sus promedios por caracteristica, factor y global`() {
        val reporte = ReporteEjecutivo(
            indicadores = emptyList(),
            respuestasEncuesta = emptyList(),
            resultadoAutoevaluacion = ResultadoAutoevaluacion(
                programa = "EGSTI",
                periodo = "20261",
                promediosPorCaracteristica = mapOf("C1" to 4.0, "C2" to null),
                promediosPorFactor = mapOf("F1" to 4.5),
                promedioGlobal = 4.5,
            ),
        )

        val texto = extraerTexto(generador.generar(reporte))

        assertTrue(texto.contains("Resultado de Autoevaluación"))
        assertTrue(texto.contains("EGSTI"))
        assertTrue(texto.contains("20261"))
        assertTrue(texto.contains("C1"))
        assertTrue(texto.contains("4.00"))
        assertTrue(texto.contains("F1"))
        assertTrue(texto.contains("Sin datos"))
    }

    @Test
    fun `omite la seccion de resultado de autoevaluacion cuando no hay datos suficientes`() {
        val reporte = ReporteEjecutivo(indicadores = emptyList(), respuestasEncuesta = emptyList())

        val texto = extraerTexto(generador.generar(reporte))

        assertTrue(!texto.contains("Resultado de Autoevaluación"))
    }

    @Test
    fun `un reporte con muchas filas genera varias paginas sin fallar`() {
        val indicadores = (1..80).map {
            IndicadorCalidad("Indicador $it", it.toDouble(), "20261", "Ingeniería")
        }
        val respuestas = (1..80).map {
            RespuestaEncuesta("R$it", TipoEstamento.ESTUDIANTE, "Factor $it", 3, "20261")
        }
        val reporte = ReporteEjecutivo(indicadores = indicadores, respuestasEncuesta = respuestas)

        val pdf = generador.generar(reporte)

        Loader.loadPDF(pdf).use { documento ->
            assertTrue(documento.numberOfPages > 1)
        }
        val texto = extraerTexto(pdf)
        assertTrue(texto.contains("Indicador 80"))
        assertTrue(texto.contains("R80"))
    }

    private fun extraerTexto(pdf: ByteArray): String =
        Loader.loadPDF(pdf).use { documento -> PDFTextStripper().getText(documento) }
}

package com.example.sgva.application

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.ActividadCiclo
import com.example.sgva.domain.CicloAutoevaluacion
import com.example.sgva.domain.Docente
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.EvaluacionDocumental
import com.example.sgva.domain.FaseCiclo
import com.example.sgva.domain.GrupoEvaluador
import com.example.sgva.domain.ParticipacionActor
import com.example.sgva.domain.PreevaluacionEvaluador
import com.example.sgva.domain.ProyectoMejoramiento
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.RespuestaEncuesta

/**
 * Doble de prueba en memoria del puerto [AcademicDataRepository]. Permite
 * ejercitar los casos de uso sin depender del adaptador de infraestructura.
 * Pública (no `internal`) para poder exponerse como bean de Spring en las
 * pruebas de integración de `infrastructure.web` (`ConfiguracionCasosDeUsoDePrueba`).
 */
class RepositorioAcademicoFalso : AcademicDataRepository {

    private val estudiantes = LinkedHashMap<String, Estudiante>()
    private val docentes = LinkedHashMap<String, Docente>()
    private val respuestasEncuesta = LinkedHashMap<String, RespuestaEncuesta>()
    private val resultadosEncuestaPregunta = LinkedHashMap<String, ResultadoEncuestaPregunta>()
    private val evaluacionesDocumentales = LinkedHashMap<String, EvaluacionDocumental>()

    override fun guardarEstudiante(estudiante: Estudiante): Estudiante {
        estudiantes[estudiante.id] = estudiante
        return estudiante
    }

    override fun buscarEstudiantePorId(id: String): Estudiante? = estudiantes[id]

    override fun listarEstudiantes(): List<Estudiante> = estudiantes.values.toList()

    override fun guardarDocente(docente: Docente): Docente {
        docentes[docente.id] = docente
        return docente
    }

    override fun buscarDocentePorId(id: String): Docente? = docentes[id]

    override fun listarDocentes(): List<Docente> = docentes.values.toList()

    override fun guardarRespuestaEncuesta(respuesta: RespuestaEncuesta): RespuestaEncuesta {
        respuestasEncuesta[respuesta.id] = respuesta
        return respuesta
    }

    override fun buscarRespuestaEncuestaPorId(id: String): RespuestaEncuesta? = respuestasEncuesta[id]

    override fun listarRespuestasEncuesta(): List<RespuestaEncuesta> = respuestasEncuesta.values.toList()

    override fun guardarResultadoEncuestaPregunta(resultado: ResultadoEncuestaPregunta): ResultadoEncuestaPregunta {
        resultadosEncuestaPregunta[claveDe(resultado.programa, resultado.periodo, resultado.codigoPregunta)] =
            resultado
        return resultado
    }

    override fun buscarResultadoEncuestaPregunta(
        programa: String,
        periodo: String,
        codigoPregunta: String,
    ): ResultadoEncuestaPregunta? = resultadosEncuestaPregunta[claveDe(programa, periodo, codigoPregunta)]

    override fun listarResultadosEncuestaPregunta(): List<ResultadoEncuestaPregunta> =
        resultadosEncuestaPregunta.values.toList()

    private fun claveDe(programa: String, periodo: String, codigoPregunta: String): String =
        "$programa|$periodo|$codigoPregunta"

    override fun guardarEvaluacionDocumental(evaluacion: EvaluacionDocumental): EvaluacionDocumental {
        evaluacionesDocumentales[claveDe(evaluacion.programa, evaluacion.periodo, evaluacion.caracteristica)] =
            evaluacion
        return evaluacion
    }

    override fun buscarEvaluacionDocumental(
        programa: String,
        periodo: String,
        caracteristica: String,
    ): EvaluacionDocumental? = evaluacionesDocumentales[claveDe(programa, periodo, caracteristica)]

    override fun listarEvaluacionesDocumentales(): List<EvaluacionDocumental> =
        evaluacionesDocumentales.values.toList()

    // ===== Módulo 5 — Seguimiento del proceso institucional (V6) =====

    private val ciclos = LinkedHashMap<String, CicloAutoevaluacion>()
    private val fases = LinkedHashMap<String, FaseCiclo>()
    private val actividades = LinkedHashMap<String, ActividadCiclo>()
    private val gruposEvaluadores = LinkedHashMap<String, GrupoEvaluador>()
    private val preevaluaciones = LinkedHashMap<String, PreevaluacionEvaluador>()
    private val participaciones = LinkedHashMap<String, ParticipacionActor>()
    private val proyectos = LinkedHashMap<String, ProyectoMejoramiento>()

    override fun guardarCiclo(ciclo: CicloAutoevaluacion): CicloAutoevaluacion {
        ciclos[ciclo.id] = ciclo
        return ciclo
    }

    override fun buscarCicloPorId(id: String): CicloAutoevaluacion? = ciclos[id]

    override fun buscarCicloPorProgramaYPeriodo(programa: String, periodo: String): CicloAutoevaluacion? =
        ciclos.values.firstOrNull { it.programa == programa && it.periodo == periodo }

    override fun listarCiclos(): List<CicloAutoevaluacion> = ciclos.values.toList()

    override fun guardarFase(fase: FaseCiclo): FaseCiclo {
        fases["${fase.ciclo}|${fase.numero}"] = fase
        return fase
    }

    override fun listarFasesPorCiclo(ciclo: String): List<FaseCiclo> = fases.values.filter { it.ciclo == ciclo }

    override fun guardarActividad(actividad: ActividadCiclo): ActividadCiclo {
        actividades["${actividad.ciclo}|${actividad.id}"] = actividad
        return actividad
    }

    override fun listarActividadesPorCiclo(ciclo: String): List<ActividadCiclo> =
        actividades.values.filter { it.ciclo == ciclo }

    override fun guardarGrupoEvaluador(grupo: GrupoEvaluador): GrupoEvaluador {
        gruposEvaluadores["${grupo.ciclo}|${grupo.taller}"] = grupo
        return grupo
    }

    override fun buscarGrupoEvaluador(ciclo: String, taller: Int): GrupoEvaluador? =
        gruposEvaluadores["$ciclo|$taller"]

    override fun listarGruposEvaluadorPorCiclo(ciclo: String): List<GrupoEvaluador> =
        gruposEvaluadores.values.filter { it.ciclo == ciclo }

    override fun guardarPreevaluacion(preevaluacion: PreevaluacionEvaluador): PreevaluacionEvaluador {
        preevaluaciones["${preevaluacion.ciclo}|${preevaluacion.caracteristica}|${preevaluacion.evaluador}"] =
            preevaluacion
        return preevaluacion
    }

    override fun buscarPreevaluacion(ciclo: String, caracteristica: String, evaluador: String): PreevaluacionEvaluador? =
        preevaluaciones["$ciclo|$caracteristica|$evaluador"]

    override fun listarPreevaluacionesPorCiclo(ciclo: String): List<PreevaluacionEvaluador> =
        preevaluaciones.values.filter { it.ciclo == ciclo }

    override fun guardarParticipacion(participacion: ParticipacionActor): ParticipacionActor {
        participaciones["${participacion.ciclo}|${participacion.actor}"] = participacion
        return participacion
    }

    override fun buscarParticipacion(ciclo: String, actor: String): ParticipacionActor? =
        participaciones["$ciclo|$actor"]

    override fun listarParticipacionPorCiclo(ciclo: String): List<ParticipacionActor> =
        participaciones.values.filter { it.ciclo == ciclo }

    override fun guardarProyecto(proyecto: ProyectoMejoramiento): ProyectoMejoramiento {
        proyectos[proyecto.id] = proyecto
        return proyecto
    }

    override fun buscarProyectoPorId(id: String): ProyectoMejoramiento? = proyectos[id]

    override fun listarProyectos(): List<ProyectoMejoramiento> = proyectos.values.toList()

    /** Vacía todos los almacenes; útil para reutilizar la misma instancia entre pruebas. */
    fun limpiar() {
        estudiantes.clear()
        docentes.clear()
        respuestasEncuesta.clear()
        resultadosEncuestaPregunta.clear()
        evaluacionesDocumentales.clear()
        ciclos.clear()
        fases.clear()
        actividades.clear()
        gruposEvaluadores.clear()
        preevaluaciones.clear()
        participaciones.clear()
        proyectos.clear()
    }
}

